#pragma once

#include <cstdint>
#include <span>

namespace fsim::semantic {

/// One declaration of package STD.STANDARD (IEEE 1076-2019 16.3), including
/// the implicit declarations of the predefined operations that the package
/// lists as comments. Generated by scripts/gen_vhdl_standard_catalog.py; the
/// VHPI library model and the overload resolution of 12.5 read the same
/// rows. Names are as 16.3 spells them (upper case, operator symbols with
/// their quotes).
///
///   since       first standard whose STANDARD has the declaration: 1987,
///               1993, 2008 or 2019 (2002 added nothing)
///   kind        'f' pure function, 'i' impure function, 't' type or subtype,
///               'r' range record type of the named type, 'a' attribute
///   result      result type, or the attribute's type
///   parameters  NAME/CLASS/TYPE items separated by commas; CLASS 'c'
///               constant or 's' signal; an anonymous formal has no NAME
///   element     the element type, in the type row of an array type
///   index       the index subtype, in the type row of an array type
struct VhdlStandardCatalogEntry {
    std::uint16_t since;
    char kind;
    const char* name;
    const char* result;
    const char* parameters;
    const char* element;
    const char* index;
};

/// The STANDARD declarations of all revisions, in the order of 16.3.
[[nodiscard]] std::span<const VhdlStandardCatalogEntry>
vhdl_standard_catalog() noexcept;

} // namespace fsim::semantic
